action.code:
if (open_list.empty()) {
    return nullptr;
}

Node* lowest_node = open_list[0];
std::size_t lowest_index = 0;

for (std::size_t i = 1; i < open_list.size(); i++) {
    if (open_list[i]->f_value < lowest_node->f_value) {
        lowest_node = open_list[i];
        lowest_index = i;
    }
}

open_list.erase(open_list.begin() + lowest_index);
return lowest_node; // END_CODE

